const request = $input.first().json;
const body = request.body || {};
const errors = [];

if (!request.ipValid) {
  errors.push('A valid IPv4 or IPv6 client address is required.');
}

if (!Array.isArray(body.ingredients) || body.ingredients.length === 0) {
  errors.push('At least one ingredient is required.');
}

if (!Number.isInteger(body.servings) || body.servings < 1 || body.servings > 12) {
  errors.push('Servings must be an integer between 1 and 12.');
}

const validTimeCategories = ['quick', 'medium', 'elaborate'];
if (!validTimeCategories.includes(body.timeCategory)) {
  errors.push('Invalid time category.');
}

const validCuisines = ['german', 'italian', 'japanese', 'indian', 'gourmet', 'fusion'];
if (!validCuisines.includes(body.cuisine)) {
  errors.push('Invalid cuisine.');
}

const validDiets = ['vegetarian', 'vegan', 'keto', 'none'];
if (!validDiets.includes(body.diet)) {
  errors.push('Invalid diet.');
}

if (!Number.isInteger(body.helperCount) || body.helperCount < 1 || body.helperCount > 4) {
  errors.push('Helper count must be an integer between 1 and 4.');
}

return [{
  json: {
    ...body,
    ip: request.ip,
    ipKey: request.ipKey,
    date: request.date,
    isValid: errors.length === 0,
    validationErrors: errors,
  },
}];

