    "yourIngredients": [{ "amount": number, "unit": "g" | "ml" | "piece", "name": "string" }],
    "extraIngredients": [{ "amount": number, "unit": "g" | "ml" | "piece", "name": "string" }],
    "directions": [{ "step": number, "title": "string", "chef": number, "parallel": boolean, "waitMinutes": number, "description": "string" }],
    "nutritionPerServing": { "energy": number, "protein": number, "carbs": number, "fat": number }
  }
]` }}

