const rawText = $input.first().json.text;

let cleaned = rawText.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```(json)?\n/, '').replace(/```$/, '').trim();
}

let recipes;
try {
  recipes = JSON.parse(cleaned);
} catch (error) {
  throw new Error('Failed to parse Gemini response as JSON: ' + error.message);
}

if (!Array.isArray(recipes) || recipes.length !== 3) {
  throw new Error('Expected exactly 3 recipes, got ' + (Array.isArray(recipes) ? recipes.length : typeof recipes));
}

const requestData = $('Validate Recipe Request').first().json;

const enrichedRecipes = recipes.map((recipe) => {
  const servings = requestData.servings;
  const perServing = recipe.nutritionPerServing;

  return {
    ...recipe,
    cuisine: requestData.cuisine,
    servings,
    likes: 0,
    nutritionTotal: {
      energy: perServing.energy * servings,
      protein: perServing.protein * servings,
      carbs: perServing.carbs * servings,
      fat: perServing.fat * servings,
    },
    createdAt: Date.now(),
  };
});

return enrichedRecipes.map((recipe) => ({ json: recipe }));

const tokenItems = $input.all();
const recipeItems = $('Parse Generated Recipes').all();

return tokenItems.map((item, index) => ({
  json: {
    idToken: item.json.idToken,
    recipe: recipeItems[index].json,
  },
}));

const firebaseResponses = $input.all();
const combinedItems = $('Combine Token and Recipe').all();

return firebaseResponses.map((response, index) => ({
  json: {
    id: response.json.name,
    ...combinedItems[index].json.recipe,
  },
}));

const items = $input.all();
const quota = $('Prepare Quota Increment').first().json.quota;
const responseBody = JSON.stringify({ recipes: items.map((item) => item.json), quota });
return [{ json: { responseBody } }];

const request = $input.first().json;
const headers = request.headers || {};
const forwardedFor = String(headers['x-forwarded-for'] || '').split(',')[0].trim();
const rawIp = forwardedFor || String(headers['x-real-ip'] || '').trim();

function parseIpv4(value) {
  const parts = value.split('.');
  if (parts.length !== 4 || parts.some((part) => !/^\d{1,3}$/.test(part))) return null;
  const numbers = parts.map(Number);
  if (numbers.some((part) => part < 0 || part > 255)) return null;
  return numbers.join('.');
}

function parseIpv6(value) {
  let address = value.toLowerCase();
  const zoneIndex = address.indexOf('%');
  if (zoneIndex >= 0) address = address.slice(0, zoneIndex);

  if (address.includes('.')) {
    const separator = address.lastIndexOf(':');
    const ipv4 = parseIpv4(address.slice(separator + 1));
    if (!ipv4) return null;
    const octets = ipv4.split('.').map(Number);
    address = `${address.slice(0, separator)}:${((octets[0] << 8) | octets[1]).toString(16)}:${((octets[2] << 8) | octets[3]).toString(16)}`;
  }

  if (!/^[0-9a-f:]+$/.test(address) || (address.match(/::/g) || []).length > 1) return null;
  const compressed = address.includes('::');
  const [leftText, rightText = ''] = address.split('::');
  const left = leftText ? leftText.split(':') : [];
  const right = rightText ? rightText.split(':') : [];
  if ([...left, ...right].some((part) => !/^[0-9a-f]{1,4}$/.test(part))) return null;

  if (!compressed && left.length !== 8) return null;
  const missing = 8 - left.length - right.length;
  if (compressed && missing < 1) return null;
  const groups = compressed ? [...left, ...Array(missing).fill('0'), ...right] : left;
  return groups.map((part) => parseInt(part, 16).toString(16)).join(':');
}

function normalizeIp(value) {
  let candidate = value.trim();
  const bracketMatch = candidate.match(/^\[([^\]]+)](?::\d+)?$/);
  if (bracketMatch) candidate = bracketMatch[1];

  const ipv4WithPort = candidate.match(/^(\d{1,3}(?:\.\d{1,3}){3}):\d+$/);
  if (ipv4WithPort) candidate = ipv4WithPort[1];

  return parseIpv4(candidate) || (candidate.includes(':') ? parseIpv6(candidate) : null);
}

const ip = normalizeIp(rawIp);
const dateParts = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Europe/Berlin',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).formatToParts(new Date()).reduce((parts, part) => ({ ...parts, [part.type]: part.value }), {});
const date = `${dateParts.year}-${dateParts.month}-${dateParts.day}`;

return [{
  json: {
    ...request,
    rawIp,
    ip: ip || '',
    ipKey: ip ? ip.replace(/\./g, '_') : '',
    ipValid: Boolean(ip),
    date,
  },
}];

const ipCountData = $('Get IP Count').first().json || {};
const totalCountData = $('Get Total Count').first().json || {};
const ipCount = Number(ipCountData.count) || 0;
const totalCount = Number(totalCountData.count) || 0;
const RECIPES_PER_REQUEST = 3;
const MAX_PER_IP = 3;
const MAX_TOTAL = 12;
const ipExceeded = ipCount + RECIPES_PER_REQUEST > MAX_PER_IP;
const totalExceeded = totalCount + RECIPES_PER_REQUEST > MAX_TOTAL;
const quotaExceeded = ipExceeded || totalExceeded;
const remainingRecipes = Math.max(0, Math.min(MAX_PER_IP - ipCount, MAX_TOTAL - totalCount));
const quotaMessage = quotaExceeded
  ? (ipExceeded
      ? 'You have reached your daily limit of 3 recipes for this network. Please try again tomorrow.'
      : 'The daily system-wide limit of 12 recipes has been reached. Please try again tomorrow.')
  : `${remainingRecipes} recipes are available today for this network.`;

return [{
  json: {
    ip: $('Extract Request Context').first().json.ip,
    ipKey: $('Extract Request Context').first().json.ipKey,
    date: $('Extract Request Context').first().json.date,
    ipCount,
    totalCount,
    recipesPerRequest: RECIPES_PER_REQUEST,
    maxPerIp: MAX_PER_IP,
    maxTotal: MAX_TOTAL,
    remainingRecipes,
    quotaExceeded,
    quotaStatus: quotaExceeded ? 'exceeded' : 'ok',
    quotaMessage,
  },
}];

const quota = {
  date: $json.date,
  perIpLimit: $json.maxPerIp,
  systemLimit: $json.maxTotal,
  ipUsed: $json.ipCount,
  totalUsed: $json.totalCount,
  remainingRecipes: $json.remainingRecipes,
  canGenerate: false,
  message: $json.quotaMessage,
};
const responseBody = JSON.stringify({ error: 'Quota exceeded', message: $json.quotaMessage, quota });
return [{ json: { responseBody } }];

const quota = $('Check Quota').first().json;
const newIpCount = quota.ipCount + quota.recipesPerRequest;
const newTotalCount = quota.totalCount + quota.recipesPerRequest;
const remainingRecipes = Math.max(0, Math.min(quota.maxPerIp - newIpCount, quota.maxTotal - newTotalCount));

return [{
  json: {
    ip: quota.ip,
    ipKey: quota.ipKey,
    date: quota.date,
    idToken: $('Sign In For Quota Check').first().json.idToken,
    quotaBody: JSON.stringify({
      [`byIp/${quota.ipKey}/count`]: newIpCount,
      'total/count': newTotalCount,
    }),
    newIpCount,
    newTotalCount,
    quota: {
      date: quota.date,
      perIpLimit: quota.maxPerIp,
      systemLimit: quota.maxTotal,
      ipUsed: newIpCount,
      totalUsed: newTotalCount,
      remainingRecipes,
      canGenerate: remainingRecipes >= quota.recipesPerRequest,
      message: remainingRecipes >= quota.recipesPerRequest
        ? `${remainingRecipes} recipes are available today for this network.`
        : 'You have reached your daily limit of 3 recipes for this network. Please try again tomorrow.',
    },
  },
}];

