const date = `${dateParts.year}-${dateParts.month}-${dateParts.day}`;

return [{ json: {
  rawIp,
  ip: ip || '',
  ipKey: ip ? ip.replace(/\./g, '_') : '',
  ipValid: Boolean(ip),
  date,
