const ipUsed = Number($json.count) || 0;
const totalUsed = Number($('Get Quota Status Total').first().json.count) || 0;
const perIpLimit = 3;
const systemLimit = 12;
const recipesPerRequest = 3;
const remainingRecipes = Math.max(0, Math.min(perIpLimit - ipUsed, systemLimit - totalUsed));
const canGenerate = remainingRecipes >= recipesPerRequest;
const message = canGenerate
  ? `${remainingRecipes} recipes are available today for this network.`
  : (ipUsed >= perIpLimit
      ? 'You have reached your daily limit of 3 recipes for this network. Please try again tomorrow.'
      : 'The daily system-wide limit of 12 recipes has been reached. Please try again tomorrow.');

return [{ json: {
  date: $('Extract Quota Status Context').first().json.date,
  perIpLimit,
  systemLimit,
  ipUsed,
  totalUsed,
  remainingRecipes,
  canGenerate,
  message,
} }];

const payload = $input.first().json;
const failure = payload.execution ?? payload.trigger ?? {};
const error = failure.error ?? {};
const cause = error.cause ?? {};

const workflowId = payload.workflow?.id ?? 'unknown';
const workflowName = payload.workflow?.name ?? 'Unknown workflow';
const executionId = payload.execution?.id ?? 'not available';
const executionUrl = payload.execution?.url ?? 'not available';
const mode = failure.mode ?? 'unknown';
const lastNode = payload.execution?.lastNodeExecuted ?? error.node?.name ?? 'trigger';
const errorName = error.name ?? cause.name ?? 'Error';
const message = error.message || cause.message || 'No error message was provided';
const timestamp = new Date().toISOString();

const logEntry = {
  event: 'n8n_workflow_error',
  timestamp,
  workflowId,
  workflowName,
  executionId,
  executionUrl,
  mode,
  lastNode,
  errorName,
  message,
};

// CODE_ENABLE_STDOUT=true forwards this structured entry to the n8n process log.
console.log(JSON.stringify(logEntry));

const text = [
  'An n8n workflow execution failed.',
  '',
  `Workflow: ${workflowName} (${workflowId})`,
  `Execution: ${executionId}`,
  `Mode: ${mode}`,
  `Failed node: ${lastNode}`,
  `Error: ${errorName}: ${message}`,
  `Time (UTC): ${timestamp}`,
  `Execution URL: ${executionUrl}`,
].join('\n');

return [{
  json: {
    ...logEntry,
    subject: `[n8n] ${workflowName} failed at ${lastNode}`,
    text,
  },
}];
